INSERT INTO liebre_market.products (id, name, description, price, discount, seller_id, category_id, createdAt, updatedAt, deletedAt) VALUES (5, 'Kit De Pesas Ejercicio', 'Home Sale traen para ti esta espectacular Set de Mancuernas de 20 KG/40LB , ahora realizar tu rutina de ejercicio será más fácil, ya que cuentas con una de las mejores Set de Mancuernas calidad/precio. El entrenamiento con pesas es uno de los deportes de fuerza más eficaces y es también muy bueno en el área de la salud y buen estado físico, así como para la rehabilitación. Los músculos se fortalecen y simultáneamente se moldean con el uso de las pesas. Por lo tanto, un entrenamiento de pesas no tiene sólo un efecto deportivo sino también un efecto estético. Con el entrenamiento de pesas la grasa corporal se reduce más eficientemente que, por ejemplo, con el ciclismo, la natación o las salidas a correr.', 134900, 5, 1, 4, '2023-01-11 20:43:08', '2023-01-18 15:09:46', null);
